// Material 3 Expressive tokens, the one design language of every platform.
// Colors are theme tokens (theme.json, generated by scripts/m3e); corners, type,
// elevation and easings are Tailwind theme entries (nsh.json). This file holds
// the same values for code: style props, springs, motions.
// Sources: androidx compose/material3 tokens (ShapeTokens, TypeScaleTokens,
// StateTokens, ElevationTokens, ExpressiveMotionTokens), m3.material.io motion
// specs (web curves), material-web elevation.

/** Every M3 color role in theme.json: `bg-<role>`, `text-<role>`, `token("<role>")`. */
export type ColorRole =
  | "primary" | "on-primary" | "primary-container" | "on-primary-container" | "inverse-primary"
  | "primary-fixed" | "primary-fixed-dim" | "on-primary-fixed" | "on-primary-fixed-variant"
  | "secondary" | "on-secondary" | "secondary-container" | "on-secondary-container"
  | "secondary-fixed" | "secondary-fixed-dim" | "on-secondary-fixed" | "on-secondary-fixed-variant"
  | "tertiary" | "on-tertiary" | "tertiary-container" | "on-tertiary-container"
  | "tertiary-fixed" | "tertiary-fixed-dim" | "on-tertiary-fixed" | "on-tertiary-fixed-variant"
  | "error" | "on-error" | "error-container" | "on-error-container"
  | "background" | "on-background" | "surface" | "on-surface" | "surface-variant" | "on-surface-variant"
  | "surface-dim" | "surface-bright" | "surface-tint"
  | "surface-container-lowest" | "surface-container-low" | "surface-container"
  | "surface-container-high" | "surface-container-highest"
  | "inverse-surface" | "inverse-on-surface" | "outline" | "outline-variant" | "scrim";

/** Corner scale in points: `rounded-<name>` (`rounded-none` and `rounded-full` are Tailwind's). */
export const corner = {
  none: 0,
  "extra-small": 4,
  small: 8,
  medium: 12,
  large: 16,
  "large-increased": 20,
  "extra-large": 28,
  "extra-large-increased": 32,
  "extra-extra-large": 48,
  full: 9999,
} as const;
export type Corner = keyof typeof corner;

/** `rounded-<corner>` per corner. */
export const rounded = Object.fromEntries(Object.keys(corner).map((k) => [k, `rounded-${k}`])) as Record<Corner, string>;

export type TypeRole =
  | "display-large" | "display-medium" | "display-small"
  | "headline-large" | "headline-medium" | "headline-small"
  | "title-large" | "title-medium" | "title-small"
  | "body-large" | "body-medium" | "body-small"
  | "label-large" | "label-medium" | "label-small";

/** Size / line height (points), weight and tracking (points), baseline and emphasized. */
export const typeScale: Record<TypeRole, { size: number; line: number; weight: number; tracking: number; emphasized: { weight: number; tracking: number } }> = {
  "display-large": { size: 57, line: 64, weight: 400, tracking: -0.2, emphasized: { weight: 500, tracking: 0 } },
  "display-medium": { size: 45, line: 52, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "display-small": { size: 36, line: 44, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "headline-large": { size: 32, line: 40, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "headline-medium": { size: 28, line: 36, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "headline-small": { size: 24, line: 32, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "title-large": { size: 22, line: 28, weight: 400, tracking: 0, emphasized: { weight: 500, tracking: 0 } },
  "title-medium": { size: 16, line: 24, weight: 500, tracking: 0.2, emphasized: { weight: 700, tracking: 0.15 } },
  "title-small": { size: 14, line: 20, weight: 500, tracking: 0.1, emphasized: { weight: 700, tracking: 0.1 } },
  "body-large": { size: 16, line: 24, weight: 400, tracking: 0.5, emphasized: { weight: 500, tracking: 0.15 } },
  "body-medium": { size: 14, line: 20, weight: 400, tracking: 0.2, emphasized: { weight: 500, tracking: 0.25 } },
  "body-small": { size: 12, line: 16, weight: 400, tracking: 0.4, emphasized: { weight: 500, tracking: 0.4 } },
  "label-large": { size: 14, line: 20, weight: 500, tracking: 0.1, emphasized: { weight: 700, tracking: 0.1 } },
  "label-medium": { size: 12, line: 16, weight: 500, tracking: 0.5, emphasized: { weight: 700, tracking: 0.5 } },
  "label-small": { size: 11, line: 16, weight: 500, tracking: 0.5, emphasized: { weight: 700, tracking: 0.5 } },
};

const weightClass: Record<number, string> = { 400: "font-normal", 500: "font-medium", 700: "font-bold" };

/** The classes of a type role: `type("title-medium")`, `type("label-large", true)` for emphasized. */
export function type(role: TypeRole, emphasized = false): string {
  const t = typeScale[role];
  const e = emphasized && t.emphasized.tracking !== t.tracking ? "-emphasized" : "";
  return `text-${role} ${weightClass[emphasized ? t.emphasized.weight : t.weight]} tracking-${role}${e}`;
}

/** State layer opacities (on the content color over the container). */
export const state = { hover: 0.08, focus: 0.1, pressed: 0.1, dragged: 0.16 } as const;

/** Disabled: container at 10% and content at 38% of on-surface. */
export const disabledOpacity = { container: 0.1, content: 0.38 } as const;

/** Elevation levels in points; `shadow-elevation-<n>` draws them. */
export const elevation = [0, 1, 3, 6, 8, 12] as const;

export type SpringSpeed = "fast" | "default" | "slow";
export type SpringKind = "spatial" | "effects";

/**
 * Expressive motion scheme. `damping` is the ratio M3 publishes; `nshDamping` is
 * the coefficient NSH's `spring()` takes (2ζ√k, mass 1). Spatial springs move
 * position, size, rotation and corners and overshoot; effects springs move color
 * and opacity and never do.
 */
export const spring: Record<SpringKind, Record<SpringSpeed, { stiffness: number; damping: number; nshDamping: number }>> = {
  spatial: {
    fast: { stiffness: 800, damping: 0.6, nshDamping: 2 * 0.6 * Math.sqrt(800) },
    default: { stiffness: 380, damping: 0.8, nshDamping: 2 * 0.8 * Math.sqrt(380) },
    slow: { stiffness: 200, damping: 0.8, nshDamping: 2 * 0.8 * Math.sqrt(200) },
  },
  effects: {
    fast: { stiffness: 3800, damping: 1, nshDamping: 2 * Math.sqrt(3800) },
    default: { stiffness: 1600, damping: 1, nshDamping: 2 * Math.sqrt(1600) },
    slow: { stiffness: 800, damping: 1, nshDamping: 2 * Math.sqrt(800) },
  },
};

/** Options for `AnimatedValue.spring(to, springTo("spatial", "fast"))`. */
export const springTo = (kind: SpringKind, speed: SpringSpeed = "default") => ({
  stiffness: spring[kind][speed].stiffness,
  damping: spring[kind][speed].nshDamping,
});

/**
 * Material's curves that mimic the springs, for class transitions and keyframes
 * (which take a curve, not physics): `ease-<kind>-<speed>` with `duration-<ms>`.
 */
export const springCurve: Record<SpringKind, Record<SpringSpeed, { ease: [number, number, number, number]; ms: number }>> = {
  spatial: {
    fast: { ease: [0.42, 1.67, 0.21, 0.9], ms: 350 },
    default: { ease: [0.38, 1.21, 0.22, 1], ms: 500 },
    slow: { ease: [0.39, 1.29, 0.35, 0.98], ms: 650 },
  },
  effects: {
    fast: { ease: [0.31, 0.94, 0.34, 1], ms: 150 },
    default: { ease: [0.34, 0.8, 0.34, 1], ms: 200 },
    slow: { ease: [0.34, 0.88, 0.34, 1], ms: 300 },
  },
};

/** `transition duration-* ease-*` for a spring's curve. */
export const transition = (kind: SpringKind, speed: SpringSpeed = "default", what = "transition") =>
  `${what} duration-${springCurve[kind][speed].ms} ease-${kind}-${speed} motion-reduce:transition-none`;

/** Keyboard focus: M3's focus indicator, a 3pt secondary outline 2pt off the edge. */
export const focusRing = "focus-visible:outline-3 focus-visible:outline-secondary focus-visible:outline-offset-2";
